enceText": "Being a part of the township, and one of the larger phases in Kalpataru Parkcity, Eternia represents the best global lifestyle that is accessible to you."}, {"model": "gpt-4.1", "value": "Eternia", "source": "visual_model", "assetId": "91042327-c345-484d-94dd-e51892586cc6", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 2, "reviewState": "unreviewed", "evidenceText": "Eternia."}, {"model": "gpt-4.1", "value": "Eternia", "source": "visual_model", "assetId": "5e5cfb6e-d217-4399-a08c-d2d540238d40", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 3, "reviewState": "unreviewed", "evidenceText": "LIFE AT ETERNIA."}, {"model": "gpt-4.1", "value": "Kalpataru Parkcity", "source": "visual_model", "assetId": "75a084ea-722e-41e9-b5ef-67aff60cb6f1", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 4, "reviewState": "unreviewed", "evidenceText": "Kalpataru Parkcity is a place of abundance that caters to all your lifestyle needs and beyond."}, {"model": "gpt-4.1", "value": "Eternia at Kalpataru Parkcity", "source": "visual_model", "assetId": "04b7e139-19f8-4ede-b8bb-2c777f307c7b", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 8, "reviewState": "unreviewed", "evidenceText": "ETERNIA At Kalpataru Parkcity"}, {"model": "gpt-4.1", "value": "Neelambar 1973", "source": "visual_model", "assetId": "d144bf61-164a-4c03-a9fe-1066dac7fb88", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 44, "reviewState": "unreviewed", "evidenceText": "NEELAMBAR 1973 NEPEAN SEA ROAD. Built in the early '70s at a height of 21 storeys, this was one of Mumbai's tallest buildings and a pioneering project in its history."}, {"model": "gpt-4.1", "value": "Kshitij 1976", "source": "visual_model", "assetId": "d144bf61-164a-4c03-a9fe-1066dac7fb88", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 44, "reviewState": "unreviewed", "evidenceText": "KSHITIJ 1976 NEPEAN SEA ROAD. With its creation, this 33-storey luxury tower transformed modern living and set lifestyle standards for others to follow."}, {"model": "gpt-4.1", "value": "Srishti 1985", "source": "visual_model", "assetId": "d144bf61-164a-4c03-a9fe-1066dac7fb88", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 44, "reviewState": "unreviewed", "evidenceText": "SRISHTI 1985 THE FIRST TOWNSHIP IN MIRA ROAD, it introduced the concept of an extra half room."}, {"model": "gpt-4.1", "value": "Kalpataru Heights 1999", "source": "visual_model", "assetId": "d144bf61-164a-4c03-a9fe-1066dac7fb88", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 44, "reviewState": "unreviewed", "evidenceText": "KALPATARU HEIGHTS 1999 CENTRAL MUMBAI. At a height of 45 storeys, this was India's tallest residential tower and an icon of the Mumbai skyline."}, {"model": "gpt-4.1", "value": "Siddhachal 1999", "source": "visual_model", "assetId": "d144bf61-164a-4c03-a9fe-1066dac7fb88", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 44, "reviewState": "unreviewed", "evidenceText": "SIDDHACHAL 1999 THANE Mumbai & Thane's first 8 bed economy homes."}, {"model": "gpt-4.1", "value": "Kalpataru Horizon 2005", "source": "visual_model", "assetId": "d144bf61-164a-4c03-a9fe-1066dac7fb88", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 44, "reviewState": "unreviewed", "evidenceText": "KALPATARU HORIZON 2005 WORLI. This was the only address to have its first residential floor starting at the 14th level with each apartment offering a sea view."}, {"model": "gpt-4.1", "value": "Kalpataru Habitat 2005", "source": "visual_model", "assetId": "d144bf61-164a-4c03-a9fe-1066dac7fb88", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 44, "reviewState": "unreviewed", "evidenceText": "KALPATARU HABITAT 2005 PAREL. Mumbai's first rooftop putting green and tennis courts changed the way the city looked at recreation and living."}, {"model": "gpt-4.1", "value": "Korum Mall 2010", "source": "visual_model", "assetId": "d144bf61-164a-4c03-a9fe-1066dac7fb88", "provider": "azure_foundry", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 44, "reviewState": "unreviewed", "evidenceText": "KORUM MALL 2010 THANE. The most loved mall with award winning design."}]}, "rera": {"evidence": [{"value": "P51700001039", "source": "document", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 1, "reviewState": "unreviewed", "evidenceText": "P51700001039"}, {"value": "P51700000927", "source": "document", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 1, "reviewState": "unreviewed", "evidenceText": "P51700000927"}, {"value": "P51700001040", "source": "document", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 1, "reviewState": "unreviewed", "evidenceText": "P51700001040"}, {"value": "P51700000732", "source": "document", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 1, "reviewState": "unreviewed", "evidenceText": "P51700000732"}, {"value": "P51700000924", "source": "document", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 1, "reviewState": "unreviewed", "evidenceText": "P51700000924"}, {"value": "P51700001278", "source": "document", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 1, "reviewState": "unreviewed", "evidenceText": "P51700001278"}, {"value": "P51700001083", "source": "document", "documentId": "03ea7b8f-83a3-4ac5-a05f-1279cca48b7b", "pageNumber": 1, "reviewState": "unreviewed", "evidenceText": "P51700001083"}, {"value": "P51700001310", "source": "document", "documentId": "03ea7